CREATE TABLE users (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE products (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL, description TEXT, unit VARCHAR(30) NOT NULL, quantity NUMERIC(15,3) NOT NULL DEFAULT 0, minimum_stock NUMERIC(15,3) NOT NULL DEFAULT 0, purchase_price NUMERIC(15,2) NOT NULL DEFAULT 0, sale_price NUMERIC(15,2) NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE materials (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL, description TEXT, unit VARCHAR(30) NOT NULL, quantity NUMERIC(15,3) NOT NULL DEFAULT 0, minimum_stock NUMERIC(15,3) NOT NULL DEFAULT 0, unit_cost NUMERIC(15,2) NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE basket_templates (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL, description TEXT, sale_price NUMERIC(15,2) NOT NULL DEFAULT 0, assembled_quantity INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE basket_products (id BIGSERIAL PRIMARY KEY, basket_id BIGINT NOT NULL REFERENCES basket_templates(id), product_id BIGINT NOT NULL REFERENCES products(id), quantity NUMERIC(15,3) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, UNIQUE(basket_id,product_id));
CREATE TABLE basket_materials (id BIGSERIAL PRIMARY KEY, basket_id BIGINT NOT NULL REFERENCES basket_templates(id), material_id BIGINT NOT NULL REFERENCES materials(id), quantity NUMERIC(15,3) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, UNIQUE(basket_id,material_id));
CREATE TABLE sales (id BIGSERIAL PRIMARY KEY, sold_at TIMESTAMPTZ NOT NULL, payment_method VARCHAR(30) NOT NULL, total NUMERIC(15,2) NOT NULL, observations TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE sale_items (id BIGSERIAL PRIMARY KEY, sale_id BIGINT NOT NULL REFERENCES sales(id), item_type VARCHAR(30) NOT NULL, reference_id BIGINT NOT NULL, item_name VARCHAR(255) NOT NULL, quantity NUMERIC(15,3) NOT NULL, unit_price NUMERIC(15,2) NOT NULL, subtotal NUMERIC(15,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE purchases (id BIGSERIAL PRIMARY KEY, establishment VARCHAR(255) NOT NULL, purchased_at TIMESTAMPTZ NOT NULL, total NUMERIC(15,2) NOT NULL, observations TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE purchase_items (id BIGSERIAL PRIMARY KEY, purchase_id BIGINT NOT NULL REFERENCES purchases(id), item_type VARCHAR(30) NOT NULL, reference_id BIGINT NOT NULL, item_name VARCHAR(255) NOT NULL, quantity NUMERIC(15,3) NOT NULL, unit_cost NUMERIC(15,2) NOT NULL, subtotal NUMERIC(15,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE expenses (id BIGSERIAL PRIMARY KEY, description VARCHAR(255) NOT NULL, category VARCHAR(255) NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, amount NUMERIC(15,2) NOT NULL, observations TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE financial_transactions (id BIGSERIAL PRIMARY KEY, type VARCHAR(20) NOT NULL, source VARCHAR(20) NOT NULL, reference_id BIGINT, description VARCHAR(255) NOT NULL, amount NUMERIC(15,2) NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE stock_movements (id BIGSERIAL PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products(id), type VARCHAR(20) NOT NULL, reason VARCHAR(30) NOT NULL, quantity NUMERIC(15,3) NOT NULL, balance_after NUMERIC(15,3) NOT NULL, reference_id BIGINT, notes VARCHAR(255), occurred_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE material_movements (id BIGSERIAL PRIMARY KEY, material_id BIGINT NOT NULL REFERENCES materials(id), type VARCHAR(20) NOT NULL, reason VARCHAR(30) NOT NULL, quantity NUMERIC(15,3) NOT NULL, balance_after NUMERIC(15,3) NOT NULL, reference_id BIGINT, notes VARCHAR(255), occurred_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_sales_sold_at ON sales(sold_at); CREATE INDEX idx_purchases_purchased_at ON purchases(purchased_at); CREATE INDEX idx_expenses_occurred_at ON expenses(occurred_at); CREATE INDEX idx_financial_occurred_at ON financial_transactions(occurred_at); CREATE INDEX idx_stock_product ON stock_movements(product_id); CREATE INDEX idx_material_movement_material ON material_movements(material_id);
